document.addEventListener("DOMContentLoaded",function(){const toggler=document.getElementById("theme-toggler");const HTML=document.getElementsByTagName("html")[0];const stored=localStorage.getItem("theme")||"light";HTML.dataset.theme=stored;if(toggler){toggler.checked=stored==="dark";toggler.addEventListener("click",()=>{const newTheme=toggler.checked?"dark":"light";HTML.dataset.theme=newTheme;localStorage.setItem("theme",newTheme)})}const langBtn=document.getElementById("language-dropdown-menu-button");const langMenu=document.getElementById("language-dropdown-menu");if(langBtn&&langMenu){const closeLang=()=>{langMenu.classList.add("hidden");langBtn.setAttribute("aria-expanded","false")};langBtn.addEventListener("click",e=>{e.stopPropagation();langMenu.classList.toggle("hidden");langBtn.setAttribute("aria-expanded",langMenu.classList.contains("hidden")?"false":"true")});document.addEventListener("click",e=>{if(!langMenu.contains(e.target)&&!langBtn.contains(e.target))closeLang()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeLang()})}let openInfo=null;function positionInfo(button,panel){const rect=button.getBoundingClientRect();const panelRect=panel.getBoundingClientRect();const gap=8;const margin=8;let left=rect.right-panelRect.width;let top=rect.bottom+gap;if(left<margin)left=margin;if(left+panelRect.width>window.innerWidth-margin){left=window.innerWidth-panelRect.width-margin}if(top+panelRect.height>window.innerHeight-margin){top=rect.top-panelRect.height-gap}if(top<margin)top=margin;panel.style.left=`${Math.max(margin,left)}px`;panel.style.top=`${Math.max(margin,top)}px`}function closeInfo(returnFocus=false){if(!openInfo)return;const{button:button,panel:panel}=openInfo;panel.classList.add("hidden");panel.setAttribute("aria-hidden","true");button.setAttribute("aria-expanded","false");openInfo=null;if(returnFocus)button.focus()}function openInfoPanel(button,panel){closeInfo();if(panel.parentElement!==document.body)document.body.appendChild(panel);panel.classList.remove("hidden");panel.setAttribute("aria-hidden","false");button.setAttribute("aria-expanded","true");openInfo={button:button,panel:panel};positionInfo(button,panel);panel.focus({preventScroll:true})}document.querySelectorAll("[data-chart-info]").forEach(wrapper=>{const button=wrapper.querySelector("[data-chart-info-toggle]");const panel=wrapper.querySelector("[data-chart-info-panel]");if(!button||!panel)return;panel.setAttribute("tabindex","-1");button.addEventListener("click",event=>{event.stopPropagation();if(openInfo&&openInfo.panel===panel)closeInfo(true);else openInfoPanel(button,panel)});panel.addEventListener("click",event=>event.stopPropagation());const closeButton=panel.querySelector("[data-chart-info-close]");if(closeButton){closeButton.addEventListener("click",event=>{event.stopPropagation();closeInfo(true)})}});document.addEventListener("click",()=>closeInfo());document.addEventListener("keydown",event=>{if(event.key==="Escape")closeInfo(true)});window.addEventListener("resize",()=>{if(openInfo)positionInfo(openInfo.button,openInfo.panel)});window.addEventListener("scroll",()=>{if(openInfo)positionInfo(openInfo.button,openInfo.panel)},true)});
